/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic       clk,
    input  logic [7:0] d,
    output logic [7:0] q
);
    always_ff @(posedge clk) begin
        q <= d;
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 0;
    logic [7:0] d = 0;
    wire [7:0] q;
    logic [7:0] expected;
    integer i;
    TopModule dut (.clk(clk), .d(d), .q(q));

    initial begin
        #1;
        clk = 1;
        #1;
        expected = 0;
        if (q !== expected) $fatal(1, "Initial capture failed");
        for (i = 0; i < 256; i = i + 1) begin
            clk = 0;
            d = 8'"'(i);
            #1;
            if (q "'!== expected) $fatal(1, "Output changed without rising edge at %0d", i);
            clk = 1;
            expected = d;
            #1;
            if (q !== expected) $fatal(1, "Capture failed at %0d", i);
            d = ~expected;
            #1;
            if (q !== expected) $fatal(1, "Output changed while clock high at %0d", i);
            clk = 0;
            #1;
            if (q !== expected) $fatal(1, "Output changed on falling edge at %0d", i);
        end
        $display("PASS: all 256 byte values captured; inter-edge stability verified");
        $finish;
    end
    initial begin
        #2000;
        $fatal(1, "Development test timed out");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
'

